import z3

def solve_sgp(w, g, s):
    n = g * s
    solver = z3.Solver()

    # X[week][golfer] = group
    X = [[z3.Int(f"x_{i}_{j}") for j in range(n)] for i in range(w)]

    for i in range(w):
        for j in range(n):
            solver.add(X[i][j] >= 0, X[i][j] < g)

    # Each group has exactly s golfers
    for i in range(w):
        for k in range(g):
            solver.add(z3.Sum([z3.If(X[i][j] == k, 1, 0) for j in range(n)]) == s)

    # No pair of golfers in the same group more than once
    for j1 in range(n):
        for j2 in range(j1 + 1, n):
            solver.add(z3.Sum([z3.If(X[i][j1] == X[i][j2], 1, 0) for i in range(w)]) <= 1)

    # Symmetry breaking
    # Week 0: golfer j is in group j // s
    for j in range(n):
        solver.add(X[0][j] == j // s)

    # Golfer 0 is always in group 0
    for i in range(w):
        solver.add(X[i][0] == 0)

    # Order groups in week i by the first golfer in each group
    # Actually, we can just say that the first appearance of groups is ordered.

    if solver.check() == z3.sat:
        m = solver.model()
        res = []
        for i in range(w):
            for j in range(n):
                res.append(m.evaluate(X[i][j]).as_long())
        return res
    else:
        return None

print(solve_sgp(8, 8, 3))
